from __future__ import annotations

import re
import unicodedata
from datetime import date
from decimal import Decimal
from functools import lru_cache

# Independent of the production parser: shared defects must not become agreement
# between the system and its oracle. This is display normalization, not inference.
_ONES = {
    "en": "zero one two three four five six seven eight nine ten eleven twelve thirteen fourteen fifteen sixteen seventeen eighteen nineteen".split(),
    "ru": "ноль один два три четыре пять шесть семь восемь девять десять одиннадцать двенадцать тринадцать четырнадцать пятнадцать шестнадцать семнадцать восемнадцать девятнадцать".split(),
}
_TENS = {
    "en": ["", "", *"twenty thirty forty fifty sixty seventy eighty ninety".split()],
    "ru": ["", "", *"двадцать тридцать сорок пятьдесят шестьдесят семьдесят восемьдесят девяносто".split()],
}
_HUNDREDS_RU = "сто двести триста четыреста пятьсот шестьсот семьсот восемьсот девятьсот".split()
_ORDINALS = {
    "en": "first second third fourth fifth sixth seventh eighth ninth tenth eleventh twelfth thirteenth fourteenth fifteenth sixteenth seventeenth eighteenth nineteenth".split(),
    "ru": "первый второй третий четвертый пятый шестой седьмой восьмой девятый десятый одиннадцатый двенадцатый тринадцатый четырнадцатый пятнадцатый шестнадцатый семнадцатый восемнадцатый девятнадцатый".split(),
}
_ORDINAL_TENS = {
    "en": "twentieth thirtieth fortieth fiftieth sixtieth seventieth eightieth ninetieth".split(),
    "ru": "двадцатый тридцатый сороковой пятидесятый шестидесятый семидесятый восьмидесятый девяностый".split(),
}
_MONTHS = {
    "en": "january february march april may june july august september october november december".split(),
    "ru": "января февраля марта апреля мая июня июля августа сентября октября ноября декабря".split(),
}
_UNITS = {
    "mm": "mm мм millimeter millimeters millimetre millimetres миллиметр миллиметра миллиметров миллиметры",
    "cm": "cm см centimeter centimeters centimetre centimetres сантиметр сантиметра сантиметров сантиметры",
    "m": "m м meter meters metre metres метр метра метров",
    "kg": "kg кг kilogram kilograms килограмм килограмма килограммов килограммы",
    "g": "g г gram grams грамм грамма граммов",
    "ml": "ml мл milliliter milliliters millilitre millilitres миллилитр миллилитра миллилитров",
    "%": "% percent percentage процентов процента процент",
    "°": "° degree degrees градус градуса градусов",
}
_UNIT_LOOKUP = {word: unit for unit, words in _UNITS.items() for word in words.split()}
_TOKEN = re.compile(
    r"\d{4}-\d{2}-\d{2}|\d{1,2}\.\d{1,2}\.\d{4}|\d+(?:[.,]\d+)?|[^\W\d_]+|[.,;:/+−\-–—×%²³<>=°±≈~*^]", re.UNICODE
)


def _ordinal_forms(word: str, locale: str) -> tuple[str, ...]:
    if locale == "en":
        return (word,)
    if word == "третий":
        return (word, "третье", "третьего")
    return (word, word[:-2] + "ого", word[:-2] + "ое")


@lru_cache(maxsize=2)
def _number_vocabulary(locale: str) -> dict[tuple[str, ...], str]:
    vocabulary: dict[tuple[str, ...], str] = {}
    for value in range(1000):
        hundreds, rest = divmod(value, 100)
        head = []
        if hundreds:
            head = [_HUNDREDS_RU[hundreds - 1]] if locale == "ru" else [_ONES[locale][hundreds], "hundred"]
        if rest < 20:
            tail = [_ONES[locale][rest]] if rest or not head else []
        else:
            tail = [_TENS[locale][rest // 10]] + ([_ONES[locale][rest % 10]] if rest % 10 else [])
        variants = [head + tail]
        if locale == "en" and head and tail:
            variants.append(head + ["and"] + tail)
        if rest:
            ordinal = (
                _ORDINALS[locale][rest - 1]
                if rest < 20
                else (_ORDINALS[locale][rest % 10 - 1] if rest % 10 else _ORDINAL_TENS[locale][rest // 10 - 2])
            )
            variants.extend(head + tail[:-1] + [form] for form in _ordinal_forms(ordinal, locale))
        for variant in variants:
            vocabulary[tuple(variant)] = str(value)
            if locale == "ru" and variant[-1] in ("один", "два"):
                for form in ("одна", "одно") if variant[-1] == "один" else ("две",):
                    vocabulary[(*variant[:-1], form)] = str(value)
    if locale == "ru":
        vocabulary[("нуль",)] = "0"
    return vocabulary


def _small_number(tokens: list[str], start: int, locale: str) -> tuple[str, int] | None:
    vocabulary = _number_vocabulary(locale)
    for end in range(min(len(tokens), start + 6), start, -1):
        if (value := vocabulary.get(tuple(tokens[start:end]))) is not None:
            return value, end
    return None


def _number(tokens: list[str], start: int, locale: str) -> tuple[str, int] | None:
    token = tokens[start]
    if re.fullmatch(r"\d+(?:[.,]\d+)?", token):
        return token.replace(",", "."), start + 1
    digits = {word: str(index) for index, word in enumerate(_ONES[locale][:10])}
    end = start
    while end < len(tokens) and tokens[end] in digits:
        end += 1
    if end - start >= 2:
        return "".join(digits[word] for word in tokens[start:end]), end
    small = _small_number(tokens, start, locale)
    thousands = {"thousand"} if locale == "en" else {"тысяча", "тысячи", "тысяч"}
    if token in thousands:
        small = ("1", start)
    if small is None:
        if locale == "ru" and token in {"двухтысячного", "двухтысячный", "двухтысячное"}:
            return "2000", start + 1
        return None
    value, end = small
    if end < len(tokens) and tokens[end] in thousands:
        remainder = _small_number(tokens, end + 1, locale) if end + 1 < len(tokens) else None
        return str(int(value) * 1000 + (int(remainder[0]) if remainder else 0)), remainder[1] if remainder else end + 1
    return value, end


def _decimal(value: str) -> str:
    return format(Decimal(value).normalize(), "f") if "." in value else value


def _numbers(tokens: list[str], locale: str) -> list[str]:
    result: list[str] = []
    index = 0
    while index < len(tokens):
        parsed = _number(tokens, index, locale)
        if parsed is None:
            result.append(tokens[index])
            index += 1
            continue
        value, end = parsed
        if end < len(tokens) and tokens[end] in {"point", "точка", "запятая"}:
            fraction = _number(tokens, end + 1, locale) if end + 1 < len(tokens) else None
            if fraction and fraction[0].isdigit():
                value, end = value + "." + fraction[0], fraction[1]
        elif end < len(tokens) and tokens[end] in {"целых", "целая", "целое", "целые"}:
            fraction = _number(tokens, end + 1, locale) if end + 1 < len(tokens) else None
            if fraction and fraction[1] < len(tokens):
                precision = {"десятая": 1, "десятых": 1, "сотая": 2, "сотых": 2, "тысячная": 3, "тысячных": 3}.get(
                    tokens[fraction[1]]
                )
                if precision and fraction[0].isdigit() and int(fraction[0]) < 10**precision:
                    value, end = value + "." + fraction[0].zfill(precision), fraction[1] + 1
        result.append(_decimal(value))
        index = end
    return result


def _valid_date(year: str, month: str, day: str) -> str | None:
    if not all(part.isdigit() for part in (year, month, day)) or len(year) != 4:
        return None
    try:
        return "date:" + date(int(year), int(month), int(day)).isoformat()
    except ValueError:
        return None


def _dates(tokens: list[str], locale: str) -> list[str]:
    months = {word: str(index) for index, word in enumerate(_MONTHS[locale], 1)}
    result: list[str] = []
    index = 0
    while index < len(tokens):
        token = tokens[index]
        is_birth_context = bool(
            set(tokens[max(0, index - 7) : index + 8]) & {"birth", "born", "рождения", "родился", "родилась"}
        )
        matched: str | None = None
        end = index + 1
        if re.fullmatch(r"\d{4}-\d{2}-\d{2}", token):
            matched = _valid_date(*token.split("-"))
        elif re.fullmatch(r"\d{1,2}\.\d{1,2}\.\d{4}", token) and locale == "ru":
            day, month, year = token.split(".")
            matched = _valid_date(year, month, day)
        elif len(token) == 8 and token.isdigit() and is_birth_context:
            matched = _valid_date(token[:4], token[4:6], token[6:])
        if matched is None:
            positions = [i for i in range(index, min(len(tokens), index + 9)) if tokens[i] not in {",", "the", "of"}]
            parts = [tokens[i] for i in positions]
            if len(parts) >= 3:
                if parts[0] in months:
                    month, day, year = months[parts[0]], parts[1], parts[2]
                elif parts[1] in months:
                    day, month, year = parts[0], months[parts[1]], parts[2]
                elif is_birth_context and len(parts[0]) == 4:
                    year, month, day = parts[:3]
                else:
                    year = month = day = ""
                year_end = 2
                if len(year) == 2 and year in {"19", "20"} and len(parts) > 3 and re.fullmatch(r"\d{2}", parts[3]):
                    year += parts[3]
                    year_end = 3
                matched = _valid_date(year, month, day)
                if matched:
                    end = positions[year_end] + 1
        if matched:
            result.append(matched)
            index = end + int(end < len(tokens) and tokens[end] in {"года", "год"})
        else:
            result.append(token)
            index += 1
    return result


@lru_cache(maxsize=32768)
def normalize_evaluation_text(text: str, locale: str, *, is_convert_units: bool = False) -> tuple[str, ...]:
    """Normalize explicit RU/EN written/spoken display forms, never clinical facts.

    Ambiguous slash dates and unsupported readings remain literal. Conversion of
    measurement units is opt-in for field comparison, not ordinary WER.
    """
    if locale not in _ONES:
        raise ValueError(f"Unsupported evaluation locale: {locale}")
    text = unicodedata.normalize("NFC", text).casefold().replace("ё", "е")
    text = text.replace("≤", "<=").replace("≥", ">=")
    text = re.sub(r"(?<=[a-zа-я])[-–](?=[a-zа-я])", " ", text)
    text = re.sub(
        r"\b(?:cm\s*/\s*s|cm\s+per\s+second|centimet(?:er|re)s?\s+per\s+second|см\s*/\s*с|см\s+в\s+секунду|сантиметр(?:ов|а|ы)?\s+в\s+секунду)\b",
        " speedunit ",
        text,
    )
    text = re.sub(
        r"\b(?:square millimet(?:er|re)s?|квадратн(?:ых|ый|ого) миллиметр(?:ов|а)?|mm[2²]|мм[2²])\b", " areaunit ", text
    )
    tokens = _dates(_numbers(_TOKEN.findall(text), locale), locale)
    tokens = [_UNIT_LOOKUP.get(token, token) for token in tokens if token not in {".", ",", ";", ":"}]
    tokens = ["-" if token in {"−", "–", "—"} else "×" if token == "x" else token for token in tokens]
    if is_convert_units:
        conversions = {"cm": ("mm", Decimal(10)), "m": ("mm", Decimal(1000)), "kg": ("g", Decimal(1000))}
        for i in range(1, len(tokens)):
            if tokens[i] in conversions and re.fullmatch(r"\d+(?:\.\d+)?", tokens[i - 1]):
                # Shared units on dimensions/ranges, area, volume and rates need
                # a dimension-aware grammar. Leave them literal rather than
                # converting only the last coordinate (11 x 5 cm != 11 x 50 mm).
                before = tokens[i - 2] if i >= 2 else None
                after = tokens[i + 1] if i + 1 < len(tokens) else None
                if before in {"×", "*", "^", "±", "by", "на", "to", "до", "/", "+", "-"} or after in {
                    "²",
                    "³",
                    "^",
                    "*",
                    "/",
                    "per",
                    "в",
                }:
                    continue
                if before and re.fullmatch(r"\d+(?:\.\d+)?", before):
                    continue
                unit, factor = conversions[tokens[i]]
                tokens[i - 1] = format((Decimal(tokens[i - 1]) * factor).normalize(), "f")
                tokens[i] = unit
    return tuple(tokens)

comparison.py.text:
from __future__ import annotations

import argparse
import json
import re
import subprocess
from typing import Any

from evaluation.voice.asr import (
    ASR_SOURCE,
    CLASSIC_SOURCE,
    CORRECTOR_SOURCE,
    FILE_ERROR_SOURCE,
    FILE_RESULT_SOURCE,
    word_error_rate,
    words,
)
from evaluation.voice.audio import AUDIO_OUTPUT_DIR
from evaluation.voice.common import ROOT, load_catalog
from evaluation.voice.generate import OUTPUT_DIR as TEXT_OUTPUT_DIR
from evaluation.voice.generate import file_sha256

ENGINES = ("speechAnalyzer", "sfSpeechRecognizer")


def _edit_distance(reference: list[str], actual: list[str]) -> int:
    previous = list(range(len(actual) + 1))
    for index, token in enumerate(reference, start=1):
        current = [index]
        for other_index, other in enumerate(actual, start=1):
            current.append(
                min(current[-1] + 1, previous[other_index] + 1, previous[other_index - 1] + (token != other))
            )
        previous = current
    return previous[-1]


def character_error_rate(reference: str, actual: str) -> float:
    expected = list(" ".join(words(reference)))
    received = list(" ".join(words(actual)))
    return _edit_distance(expected, received) / len(expected) if expected else float(bool(received))


def _critical_retention(case: dict[str, Any], actual: str) -> dict[str, bool | None]:
    """Legacy token presence diagnostic; does NOT test subject-bound clinical facts.

    Kept for reproducing historical diagnostic tools. The v2 matrix does not use
    this as a clinical quality metric; see score_clinical_content instead.
    """
    facts = case["expectedFacts"]
    lowered = actual.casefold()
    received = set(words(actual))
    measurements = [fact for fact in facts if fact["kind"] == "measurement"]
    negations = [fact for fact in facts if fact["kind"] == "negation"]
    sides = [fact["value"] for fact in facts if fact["kind"] == "side"]
    millimeter_forms = {"mm", "millimeter", "millimeters", "мм", "миллиметр", "миллиметра", "миллиметров"}
    centimeter_forms = {"cm", "centimeter", "centimeters", "см", "сантиметр", "сантиметра", "сантиметров"}
    unit_forms = {
        "mm": millimeter_forms,
        "мм": millimeter_forms,
        "cm": centimeter_forms,
        "см": centimeter_forms,
        "cm/s": {
            "cm/s",
            "cm per second",
            "centimeter per second",
            "centimeters per second",
            "см/с",
            "см в секунду",
            "сантиметра в секунду",
            "сантиметров в секунду",
        },
        "см/с": {
            "cm/s",
            "cm per second",
            "centimeter per second",
            "centimeters per second",
            "см/с",
            "см в секунду",
            "сантиметра в секунду",
            "сантиметров в секунду",
        },
        "ml": {"ml", "milliliter", "milliliters", "мл", "миллилитр", "миллилитров"},
        "мл": {"ml", "milliliter", "milliliters", "мл", "миллилитр", "миллилитров"},
    }
    number_retained = (
        all(re.search(rf"(?<!\d){re.escape(str(fact['value']))}(?!\d)", lowered) for fact in measurements)
        if measurements
        else None
    )
    # ASR often joins a measurement and its unit ("5mm", "50см/с").
    # Split only that digit-to-letter boundary before checking literal units.
    unit_text = re.sub(r"(?<=\d)(?=[^\W\d_])", " ", actual)
    normalized_text = f" {' '.join(words(unit_text))} "
    unit_retained = (
        all(
            any(
                f" {' '.join(words(form))} " in normalized_text for form in unit_forms.get(fact["unit"], {fact["unit"]})
            )
            for fact in measurements
        )
        if measurements
        else None
    )
    negation_retained = bool(received & {"no", "not", "нет", "не", "без"}) if negations else None
    if sides:
        side_retained = all(
            ("right" in received or any(token.startswith("прав") for token in received))
            if side == "right"
            else ("left" in received or any(token.startswith("лев") for token in received))
            for side in sides
        )
    else:
        side_retained = None
    return {"negation": negation_retained, "side": side_retained, "number": number_retained, "unit": unit_retained}


def _summarize(rows: list[dict[str, Any]]) -> dict[str, Any]:
    ok = [row for row in rows if row["status"] == "ok"]
    return {
        "requested": len(rows),
        "recognized": len(ok),
        "skipped": sum(row["status"] == "skipped" for row in rows),
        "failed": sum(row["status"] == "failed" for row in rows),
        "meanWER": sum(row["wer"] for row in ok) / len(ok) if ok else None,
        "meanCER": sum(row["cer"] for row in ok) / len(ok) if ok else None,
        "criticalRetention": {
            kind: {
                "retained": sum(row["criticalRetention"][kind] is True for row in ok),
                "eligible": sum(row["criticalRetention"][kind] is not None for row in ok),
            }
            for kind in ("negation", "side", "number", "unit")
        },
    }


def run_comparison(mode: str = "quick", *, limit: int | None = None, score_only: bool = False) -> dict[str, Any]:
    directory = AUDIO_OUTPUT_DIR / (mode if limit is None else f"{mode}-smoke-{limit}")
    manifest_path = directory / "manifest.json"
    manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
    corpus_path = TEXT_OUTPUT_DIR / "regression.jsonl"
    if manifest["regressionSha256"] != file_sha256(corpus_path):
        raise ValueError("Audio and text corpora differ")
    cases = {
        row["id"]: row for line in corpus_path.read_text(encoding="utf-8").splitlines() if (row := json.loads(line))
    }
    _, terms = load_catalog()
    variants = ("clean",) if mode == "quick" else ("clean", "noisy")
    jobs: list[dict[str, Any]] = []
    lookup: dict[str, tuple[dict[str, Any], str, str, bool]] = {}
    unavailable: list[dict[str, Any]] = []
    for entry in manifest["entries"]:
        case = cases[entry["caseId"]]
        for variant in variants:
            if entry["status"] != "ok":
                unavailable.append(
                    {"caseId": case["id"], "variant": variant, "status": "skipped", "reason": "Audio unavailable"}
                )
                continue
            audio_path = ROOT / entry[variant]["path"]
            if file_sha256(audio_path) != entry[variant]["sha256"]:
                raise ValueError(f"Audio hash mismatch: {audio_path}")
            for engine in ENGINES:
                for hints in (False, True):
                    job_id = f"{case['id']}::{variant}::{engine}::{int(hints)}"
                    jobs.append(
                        {
                            "id": job_id,
                            "locale": case["locale"],
                            "audioPath": str(audio_path),
                            "contextualStrings": terms[case["locale"]][case["examinationTypeId"]],
                            "engine": engine,
                            "isHintingEnabled": hints,
                        }
                    )
                    lookup[job_id] = (case, variant, engine, hints)
    jobs_path = directory / "comparison-jobs.json"
    results_path = directory / "comparison-results.jsonl"
    jobs_path.write_text(json.dumps(jobs, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    executable = AUDIO_OUTPUT_DIR / "voice-audio-asr"
    if not score_only:
        subprocess.run(
            [
                "swiftc",
                "-O",
                "-parse-as-library",
                "-module-cache-path",
                str(AUDIO_OUTPUT_DIR / "swift-module-cache"),
                *map(str, (ASR_SOURCE, CORRECTOR_SOURCE, CLASSIC_SOURCE, FILE_RESULT_SOURCE, FILE_ERROR_SOURCE)),
                "-o",
                str(executable),
            ],
            check=True,
        )
        subprocess.run(
            [str(executable), str(jobs_path), str(results_path)], check=True, timeout=max(120, len(jobs) * 40)
        )
    results = [json.loads(line) for line in results_path.read_text(encoding="utf-8").splitlines()]
    if [row["id"] for row in results] != [job["id"] for job in jobs]:
        raise ValueError("ASR results do not match the requested jobs")
    scored: list[dict[str, Any]] = []
    for result in results:
        case, variant, engine, hints = lookup[result["id"]]
        for corrected in (False, True):
            item = {
                "caseId": case["id"],
                "locale": case["locale"],
                "examinationTypeId": case["examinationTypeId"],
                "variant": variant,
                "engine": engine,
                "hints": hints,
                "correction": corrected,
                "status": result["status"],
                "reason": result.get("reason"),
                "elapsedSeconds": result.get("elapsedSeconds"),
            }
            if result["status"] == "ok":
                transcript = result["correctedText" if corrected else "rawText"]
                item.update(
                    text=transcript,
                    wer=word_error_rate(case["spokenText"], transcript),
                    cer=character_error_rate(case["spokenText"], transcript),
                    criticalRetention=_critical_retention(case, transcript),
                )
            scored.append(item)
    by_group: dict[str, Any] = {}
    for locale in ("en", "ru"):
        for variant in variants:
            for engine in ENGINES:
                for hints in (False, True):
                    for corrected in (False, True):
                        key = f"{locale}/{variant}/{engine}/hints={hints}/correction={corrected}"
                        by_group[key] = _summarize(
                            [
                                row
                                for row in scored
                                if row["locale"] == locale
                                and row["variant"] == variant
                                and row["engine"] == engine
                                and row["hints"] == hints
                                and row["correction"] == corrected
                            ]
                        )
    by_type = {
        f"{locale}/{type_id}": {
            f"{engine}/hints={hints}/correction={corrected}": _summarize(
                [
                    row
                    for row in scored
                    if row["locale"] == locale
                    and row["examinationTypeId"] == type_id
                    and row["engine"] == engine
                    and row["hints"] == hints
                    and row["correction"] == corrected
                ]
            )
            for engine in ENGINES
            for hints in (False, True)
            for corrected in (False, True)
        }
        for locale in ("en", "ru")
        for type_id in sorted({case["examinationTypeId"] for case in cases.values()})
    }
    paired_deltas: dict[str, Any] = {}
    for locale in ("en", "ru"):
        for variable, before_filter, after_filter in (
            (
                "hints",
                {"engine": "speechAnalyzer", "hints": False, "correction": True},
                {"engine": "speechAnalyzer", "hints": True, "correction": True},
            ),
            (
                "correction",
                {"engine": "speechAnalyzer", "hints": True, "correction": False},
                {"engine": "speechAnalyzer", "hints": True, "correction": True},
            ),
            (
                "engine",
                {"engine": "sfSpeechRecognizer", "hints": True, "correction": True},
                {"engine": "speechAnalyzer", "hints": True, "correction": True},
            ),
        ):
            before = {
                (row["caseId"], row["variant"]): row
                for row in scored
                if row["locale"] == locale and all(row[key] == value for key, value in before_filter.items())
            }
            after = {
                (row["caseId"], row["variant"]): row
                for row in scored
                if row["locale"] == locale and all(row[key] == value for key, value in after_filter.items())
            }
            pairs = [
                (old, after[key])
                for key, old in before.items()
                if key in after and old["status"] == after[key]["status"] == "ok"
            ]
            paired_deltas[f"{locale}/{variable}"] = {
                "paired": len(pairs),
                "improvedWER": sum(new["wer"] < old["wer"] for old, new in pairs),
                "worsenedWER": sum(new["wer"] > old["wer"] for old, new in pairs),
                "meanWERDelta": sum(new["wer"] - old["wer"] for old, new in pairs) / len(pairs) if pairs else None,
                "criticalRegressions": {
                    kind: sum(
                        old["criticalRetention"][kind] is True and new["criticalRetention"][kind] is False
                        for old, new in pairs
                    )
                    for kind in ("negation", "side", "number", "unit")
                },
            }
    report = {
        "schemaVersion": 1,
        "platform": "macOS",
        "isIOSBaseline": False,
        "audioMode": mode,
        "audioManifestSha256": file_sha256(manifest_path),
        "requestedRecognitionJobs": len(jobs),
        "unavailableAudio": unavailable,
        "byGroup": by_group,
        "byExaminationType": by_type,
        "pairedDeltas": paired_deltas,
        "results": scored,
        "note": "Literal-token retention on synthetic TTS is not a clinical semantic accuracy measure.",
    }
    (directory / "comparison-report.json").write_text(
        json.dumps(report, ensure_ascii=False, indent=2) + "\n", encoding="utf-8"
    )
    lines = [
        "# Local ASR comparison on synthetic WAV",
        "",
        f"Mode: {mode}; recognition jobs: {len(jobs)}. Each audio file is used by both engines and both hint settings.",
        "The correction variants are scored from the same raw transcript.",
        "",
        "| Locale | Change | Paired | Better WER | Worse WER | Mean Δ WER | Critical regressions |",
        "|---|---|---:|---:|---:|---:|---|",
    ]
    for locale in ("en", "ru"):
        for variable in ("hints", "correction", "engine"):
            delta = paired_deltas[f"{locale}/{variable}"]
            critical = ", ".join(f"{kind}: {count}" for kind, count in delta["criticalRegressions"].items())
            mean_delta = f"{delta['meanWERDelta']:+.4f}" if delta["meanWERDelta"] is not None else "not measured"
            lines.append(
                f"| {locale} | {variable} | {delta['paired']} | {delta['improvedWER']} | "
                f"{delta['worsenedWER']} | {mean_delta} | {critical} |"
            )
    lines.extend(
        [
            "",
            "## By examination type",
            "",
            "| Locale | Type | Analyzer WER, hints off | Analyzer WER, hints on | Corrected WER |",
            "|---|---|---:|---:|---:|",
        ]
    )
    for name, variants_by_type in by_type.items():
        locale, type_id = name.split("/", 1)

        def display(key: str) -> str:
            value = variants_by_type[key]["meanWER"]
            return f"{value:.3f}" if value is not None else "not measured"

        lines.append(
            f"| {locale} | {type_id} | "
            f"{display('speechAnalyzer/hints=False/correction=False')} | "
            f"{display('speechAnalyzer/hints=True/correction=False')} | "
            f"{display('speechAnalyzer/hints=True/correction=True')} |"
        )
    lines.extend(
        [
            "",
            "Critical retention is a literal check of measurement values, units, side words and negation markers. "
            "It does not establish semantic correctness of a medical statement.",
            "Unavailable recognizer results are excluded from WER denominators and remain visible in comparison-report.json.",
            "",
        ]
    )
    (directory / "comparison.md").write_text("\n".join(lines), encoding="utf-8")
    return report


def main() -> None:
    parser = argparse.ArgumentParser(description="Compare local ASR engines and vocabulary on the same WAV files")
    parser.add_argument("--mode", choices=("quick", "extended"), default="quick")
    parser.add_argument("--limit", type=int)
    parser.add_argument("--score-only", action="store_true")
    args = parser.parse_args()
    report = run_comparison(args.mode, limit=args.limit, score_only=args.score_only)
    print(f"Recognition jobs: {report['requestedRecognitionJobs']}")
    print(
        f"Report: {AUDIO_OUTPUT_DIR / (args.mode if args.limit is None else f'{args.mode}-smoke-{args.limit}') / 'comparison-report.json'}"
    )


if __name__ == "__main__":
    main()

